{
  "name": "opencode-grok-usage",
  "version": "0.1.1",
  "description": "OpenCode V2 plugin: live Grok usage in the sidebar \u2014 SuperGrok/X Premium+ weekly credits or xAI API rate limits and balance.",
  "type": "module",
  "license": "MIT",
  "exports": {
    ".": "./src/index.ts",
    "./rpc": "./src/rpc.ts",
    "./tui": "./src/tui.tsx"
  },
  "files": [
    "src",
    "bin",
    "README.md",
    "LEGAL.md",
    "SECURITY.md"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "grok",
    "xai",
    "usage",
    "quota"
  ],
  "scripts": {
    "test": "node --test test/*.test.ts",
    "typecheck": "tsc --noEmit",
    "install:local": "V=$(node -p \"require('./package.json').version\"); D=\"$HOME/.local/share/opencode-grok-usage/$V\"; mkdir -p \"$D\"; rsync -a --delete --exclude node_modules --exclude package-lock.json src bin README.md LEGAL.md SECURITY.md LICENSE package.json \"$D/\"; cd \"$D\" && npm install --omit=dev --silent && echo \"installed to $D\""
  },
  "dependencies": {
    "@opencode/plugin": "^2.2.5"
  },
  "devDependencies": {
    "@opencode/theme": "2.2.5",
    "@opentui/core": "0.8.1",
    "@opentui/solid": "0.8.1",
    "@types/node": "^24.0.0",
    "solid-js": "1.9.18",
    "typescript": "^5.9.0"
  },
  "engines": {
    "node": ">=22.18"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/officialPlocki/opencode-grok-usage.git"
  },
  "homepage": "https://github.com/officialPlocki/opencode-grok-usage#readme",
  "bugs": {
    "url": "https://github.com/officialPlocki/opencode-grok-usage/issues"
  },
  "bin": {
    "opencode-grok-usage": "./bin/grok-usage.js"
  }
}
